/**
 * @summary Get public payment details (no auth)
 */
export const getGetPublicPaymentUrl = (transactionId: string) => {
  return `/api/public/payment/${transactionId}`;
};

export const getPublicPayment = async (
  transactionId: string,
  options?: RequestInit,
): Promise<PublicPaymentDetails> => {
  return customFetch<PublicPaymentDetails>(
    getGetPublicPaymentUrl(transactionId),
    {
      ...options,
      method: "GET",
    },
  );
};

export const getGetPublicPaymentQueryKey = (transactionId: string) => {
  return [`/api/public/payment/${transactionId}`] as const;
};

export const getGetPublicPaymentQueryOptions = <
  TData = Awaited<ReturnType<typeof getPublicPayment>>,
  TError = ErrorType<ErrorResponse>,
>(
  transactionId: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getPublicPayment>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getGetPublicPaymentQueryKey(transactionId);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof getPublicPayment>>
  > = ({ signal }) =>
    getPublicPayment(transactionId, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!transactionId,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getPublicPayment>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

